  PRIMARY KEY (`id`),
  UNIQUE KEY `health_guides_slug_unique` (`slug`),
  KEY `health_guides_is_active_category_order_index` (`is_active`, `category`, `order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `migrations` (
