INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`) VALUES (1, 1, 1, 'Manfaat Minum Air Putih yang Cukup Setiap Hari', 'manfaat-minum-air-putih-yang-cukup-setiap-hari', 'Air adalah komponen penting tubuh manusia. Mengetahui manfaat minum air yang cukup setiap hari dapat mendorong kebiasaan hidup yang lebih sehat.', '<p>Tubuh manusia terdiri dari sekitar 60% air. Menjaga kecukupan asupan air setiap hari adalah salah satu fondasi utama kesehatan yang sering diabaikan.</p><h3>Manfaat Minum Air yang Cukup</h3><ul><li>Menjaga fungsi organ tubuh secara optimal</li><li>Membantu proses pencernaan</li><li>Mengatur suhu tubuh</li><li>Meningkatkan konsentrasi dan fungsi otak</li><li>Membantu pembuangan racun melalui urin</li></ul><p>Rekomendasi umum adalah minum minimal 8 gelas (2 liter) air per hari, namun kebutuhan individu bisa bervariasi tergantung aktivitas dan kondisi kesehatan.</p>', NULL, 'Air adalah komponen penting tubuh manusia. Mengetahui manfaat minum air yang cukup setiap hari dapat mendorong kebiasaan hidup yang lebih sehat.', 'published', '2026-09-12 13:53:15', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`) VALUES (2, 1, 2, '5 Cara Efektif Mengelola Stres di Era Modern', '5-cara-efektif-mengelola-stres-di-era-modern', 'Stres adalah respons alami tubuh terhadap tekanan. Pelajari cara-cara efektif untuk mengelola stres agar kualitas hidup Anda tetap terjaga.', '<p>Di era modern yang serba cepat, stres menjadi salah satu tantangan kesehatan yang paling umum dihadapi. Mengelola stres dengan baik sangat penting untuk kesejahteraan mental dan fisik.</p><h3>5 Cara Mengelola Stres</h3><ol><li><strong>Olahraga teratur</strong> – Aktivitas fisik membantu melepaskan endorfin yang meningkatkan suasana hati</li><li><strong>Meditasi dan pernapasan dalam</strong> – Teknik ini terbukti menurunkan kadar kortisol (hormon stres)</li><li><strong>Tidur yang cukup</strong> – Tidur 7-9 jam per malam membantu pemulihan tubuh dan pikiran</li><li><strong>Berbicara dengan orang terpercaya</strong> – Berbagi masalah dapat meringankan beban pikiran</li><li><strong>Batasi paparan media sosial</strong> – Kurangi konsumsi konten negatif yang memperparah kecemasan</li></ol>', NULL, 'Stres adalah respons alami tubuh terhadap tekanan. Pelajari cara-cara efektif untuk mengelola stres agar kualitas hidup Anda tetap terjaga.', 'published', '2026-09-28 13:53:15', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`) VALUES (3, 1, 3, 'Panduan Gizi Seimbang untuk Hidup Lebih Sehat', 'panduan-gizi-seimbang-untuk-hidup-lebih-sehat', 'Gizi seimbang bukan sekadar diet, melainkan pola makan berkelanjutan yang memenuhi semua kebutuhan nutrisi tubuh secara optimal.', '<p>Gizi seimbang adalah kunci utama menjaga kesehatan jangka panjang. Tubuh membutuhkan berbagai nutrisi dalam jumlah yang tepat untuk dapat berfungsi dengan optimal.</p><h3>Komponen Gizi Seimbang</h3><ul><li><strong>Karbohidrat kompleks</strong> – Nasi merah, oat, ubi</li><li><strong>Protein</strong> – Daging tanpa lemak, ikan, kacang-kacangan, telur</li><li><strong>Lemak sehat</strong> – Alpukat, minyak zaitun, kacang almond</li><li><strong>Serat</strong> – Sayuran, buah-buahan, biji-bijian</li><li><strong>Vitamin dan mineral</strong> – Berasal dari variasi makanan yang beragam</li></ul><p>Ingat, tidak ada makanan "ajaib" yang bisa memenuhi semua kebutuhan gizi. Variasi dan keseimbangan adalah kuncinya.</p>', NULL, 'Gizi seimbang bukan sekadar diet, melainkan pola makan berkelanjutan yang memenuhi semua kebutuhan nutrisi tubuh secara optimal.', 'published', '2026-10-02 13:53:15', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`) VALUES (4, 1, 4, 'Tips Menjaga Imunitas Anak agar Tidak Mudah Sakit', 'tips-menjaga-imunitas-anak-agar-tidak-mudah-sakit', 'Sistem imun anak yang kuat adalah investasi terbaik untuk tumbuh kembangnya. Berikut tips praktis yang bisa Anda terapkan sehari-hari.', '<p>Anak-anak rentan terhadap infeksi karena sistem imun mereka masih dalam proses perkembangan. Ada banyak cara yang dapat dilakukan orang tua untuk membantu memperkuat daya tahan tubuh anak.</p><h3>Tips Memperkuat Imunitas Anak</h3><ul><li>Pastikan anak mendapat vaksinasi sesuai jadwal</li><li>Berikan makanan bergizi dengan banyak sayur dan buah</li><li>Pastikan anak tidur cukup sesuai usianya</li><li>Ajarkan kebiasaan cuci tangan yang benar</li><li>Batasi paparan asap rokok dan polusi</li><li>Dorong anak untuk aktif bermain di luar rumah</li></ul>', NULL, 'Sistem imun anak yang kuat adalah investasi terbaik untuk tumbuh kembangnya. Berikut tips praktis yang bisa Anda terapkan sehari-hari.', 'published', '2026-09-26 13:53:15', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`) VALUES (5, 1, 5, 'Mulai Olahraga dari Nol: Panduan untuk Pemula', 'mulai-olahraga-dari-nol-panduan-untuk-pemula', 'Memulai kebiasaan olahraga bisa terasa berat di awal. Panduan ini akan membantu Anda memulai perjalanan aktif dengan cara yang aman dan menyenangkan.', '<p>Olahraga teratur adalah salah satu kebiasaan terbaik yang bisa Anda tanamkan untuk kesehatan jangka panjang. Bagi pemula, kuncinya adalah memulai perlahan dan konsisten.</p><h3>Langkah Memulai Olahraga untuk Pemula</h3><ol><li><strong>Tetapkan tujuan yang realistis</strong> – Mulai dengan target kecil seperti 15-20 menit, 3 kali seminggu</li><li><strong>Pilih aktivitas yang Anda nikmati</strong> – Berjalan, bersepeda, renang, atau senam</li><li><strong>Lakukan pemanasan</strong> – Selalu mulai dengan pemanasan 5-10 menit</li><li><strong>Tingkatkan intensitas bertahap</strong> – Jangan langsung terlalu keras di awal</li><li><strong>Istirahat yang cukup</strong> – Beri waktu tubuh untuk pulih antar sesi olahraga</li></ol>', NULL, 'Memulai kebiasaan olahraga bisa terasa berat di awal. Panduan ini akan membantu Anda memulai perjalanan aktif dengan cara yang aman dan menyenangkan.', 'published', '2026-09-16 13:53:15', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `services` (`id`, `name`, `slug`, `description`, `content`, `icon`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (1, 'Info Obat', 'info-obat', 'Temukan informasi lengkap mengenai obat-obatan, fungsi, dosis, dan efek sampingnya.', '<p>Layanan Info Obat SEHATIN menyediakan database informasi obat yang komprehensif. Anda dapat mencari informasi tentang berbagai jenis obat, mulai dari obat bebas hingga obat resep, termasuk komposisi, indikasi, kontraindikasi, dan cara penggunaan yang tepat.</p><p><strong>Disclaimer:</strong> Informasi ini bersifat edukatif dan tidak menggantikan konsultasi dengan apoteker atau tenaga kesehatan profesional.</p>', 'fas fa-pills', NULL, 1, 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `services` (`id`, `name`, `slug`, `description`, `content`, `icon`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (2, 'Info Penyakit', 'info-penyakit', 'Pelajari gejala, penyebab, dan cara pencegahan berbagai penyakit secara mudah.', '<p>Layanan Info Penyakit menyajikan informasi medis yang mudah dipahami tentang berbagai kondisi kesehatan. Dari penyakit umum seperti flu dan demam, hingga penyakit kronis seperti diabetes dan hipertensi.</p><p><strong>Disclaimer:</strong> Informasi di SEHATIN bersifat edukatif dan tidak menggantikan diagnosis atau konsultasi dengan tenaga kesehatan.</p>', 'fas fa-notes-medical', NULL, 1, 2, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `services` (`id`, `name`, `slug`, `description`, `content`, `icon`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (3, 'Edukasi Kesehatan', 'edukasi-kesehatan', 'Tingkatkan literasi kesehatan Anda melalui konten edukatif yang terpercaya.', '<p>Program Edukasi Kesehatan SEHATIN hadir untuk meningkatkan kesadaran masyarakat tentang pentingnya menjaga kesehatan. Kami menyajikan konten kesehatan yang akurat, mudah dipahami, dan dapat diterapkan dalam kehidupan sehari-hari.</p>', 'fas fa-graduation-cap', NULL, 1, 3, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `services` (`id`, `name`, `slug`, `description`, `content`, `icon`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (4, 'Panduan Kesehatan', 'panduan-kesehatan', 'Panduan praktis menjaga kesehatan dari berbagai aspek kehidupan sehari-hari.', '<p>Panduan Kesehatan SEHATIN menyediakan langkah-langkah praktis untuk menjaga kesehatan optimal. Mulai dari panduan olahraga, pola tidur yang baik, manajemen stres, hingga tips menjaga imunitas tubuh.</p>', 'fas fa-book-medical', NULL, 1, 4, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `services` (`id`, `name`, `slug`, `description`, `content`, `icon`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (5, 'Direktori Kesehatan', 'direktori-kesehatan', 'Temukan fasilitas dan layanan kesehatan terpercaya di sekitar Anda.', '<p>Direktori Kesehatan SEHATIN memudahkan Anda menemukan informasi tentang berbagai fasilitas layanan kesehatan. Kami menyediakan informasi tentang rumah sakit, klinik, puskesmas, dan fasilitas kesehatan lainnya.</p>', 'fas fa-map-marker-alt', NULL, 1, 5, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (1, 'Apa itu SEHATIN?', 'SEHATIN adalah portal informasi kesehatan digital yang menyediakan artikel kesehatan berkualitas, informasi obat, informasi penyakit, dan panduan kesehatan untuk masyarakat Indonesia. Semua konten disajikan dengan bahasa yang mudah dipahami dan berbasis sumber terpercaya.', 1, 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (2, 'Apakah informasi di SEHATIN dapat dijadikan pengganti konsultasi dokter?', 'Tidak. Seluruh informasi yang tersedia di SEHATIN bersifat edukatif dan bertujuan untuk meningkatkan literasi kesehatan masyarakat. Informasi ini tidak menggantikan diagnosis, saran medis, atau konsultasi dengan dokter dan tenaga kesehatan profesional. Untuk kondisi kesehatan yang serius, selalu konsultasikan dengan dokter Anda.', 1, 2, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (3, 'Bagaimana cara mendaftar akun di SEHATIN?', 'Anda dapat mendaftar akun SEHATIN dengan mengisi formulir pendaftaran menggunakan email dan kata sandi, atau lebih mudah dengan login menggunakan akun Google Anda. Klik tombol "Daftar" di pojok kanan atas halaman untuk memulai.', 1, 3, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (4, 'Apakah konten di SEHATIN gratis?', 'Ya, seluruh konten artikel dan informasi kesehatan di SEHATIN dapat diakses secara gratis oleh semua pengguna, baik yang sudah mendaftar maupun yang belum. Kami berkomitmen untuk menyediakan informasi kesehatan yang terjangkau dan mudah diakses oleh seluruh masyarakat.', 1, 4, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (5, 'Bagaimana cara mengganti bahasa tampilan di SEHATIN?', 'SEHATIN mendukung dua bahasa: Bahasa Indonesia dan English. Untuk mengganti bahasa, klik ikon bahasa (🌐) yang tersedia di bagian header/navigasi website, kemudian pilih bahasa yang Anda inginkan. Pilihan bahasa akan tersimpan otomatis untuk kunjungan berikutnya.', 1, 5, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `static_pages` (`id`, `slug`, `title`, `content`, `created_at`, `updated_at`) VALUES (1, 'tentang-sehatin', 'Tentang SEHATIN', '<h2>Mengenal SEHATIN</h2>\n<p>SEHATIN adalah platform informasi kesehatan digital yang didedikasikan untuk membantu masyarakat Indonesia mendapatkan akses mudah terhadap informasi kesehatan yang akurat, terpercaya, dan mudah dipahami.</p>\n\n<h3>Visi Kami</h3>\n<p>Menjadi portal referensi kesehatan terdepan yang memberdayakan masyarakat Indonesia untuk membuat keputusan kesehatan yang lebih baik melalui literasi kesehatan yang kuat.</p>\n\n<h3>Misi Kami</h3>\n<ul>\n<li>Menyajikan konten kesehatan yang akurat dan berbasis bukti ilmiah</li>\n<li>Membuat informasi kesehatan mudah dipahami oleh masyarakat umum</li>\n<li>Mendukung peningkatan literasi kesehatan masyarakat Indonesia</li>\n<li>Menyediakan referensi sehat yang dapat diakses kapan saja dan di mana saja</li>\n</ul>\n\n<h3>Komitmen Kami</h3>\n<p>Setiap konten yang dipublikasikan di SEHATIN melalui proses kurasi yang ketat. Kami berkomitmen untuk selalu menyajikan informasi yang bertanggung jawab dan tidak menyesatkan.</p>\n\n<div class="disclaimer-box">\n<strong>⚠️ Penting:</strong> Informasi di SEHATIN bersifat edukatif dan tidak menggantikan diagnosis atau konsultasi dengan tenaga kesehatan profesional. Untuk kondisi medis yang serius, selalu berkonsultasi dengan dokter Anda.\n</div>', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `static_pages` (`id`, `slug`, `title`, `content`, `created_at`, `updated_at`) VALUES (2, 'kebijakan-privasi', 'Kebijakan Privasi', '<p><em>Terakhir diperbarui: 03 October 2026</em></p>\n\n<h2>Kebijakan Privasi SEHATIN</h2>\n<p>SEHATIN menghormati privasi Anda dan berkomitmen untuk melindungi data pribadi yang Anda berikan kepada kami. Kebijakan Privasi ini menjelaskan bagaimana kami mengumpulkan, menggunakan, dan melindungi informasi Anda.</p>\n\n<h3>1. Informasi yang Kami Kumpulkan</h3>\n<p>Kami dapat mengumpulkan informasi berikut:</p>\n<ul>\n<li>Nama dan alamat email saat Anda mendaftar akun</li>\n<li>Informasi profil Google jika Anda login menggunakan akun Google</li>\n<li>Data penggunaan website untuk analitik jika fitur tersebut digunakan dan Anda menyetujuinya</li>\n</ul>\n\n<h3>Cookie dan Penyimpanan di Browser</h3>\n<p>SEHATIN menggunakan cookie esensial untuk menjaga sesi, keamanan, login, dan pilihan bahasa. Pilihan Anda pada banner cookie (menerima semua cookie atau hanya cookie esensial) disimpan di penyimpanan lokal browser agar banner tidak terus muncul. Pilihan ini dapat diubah kapan saja melalui tautan Pengaturan Cookie di footer. Jika fitur cookie opsional seperti analitik diaktifkan, pilihan Anda akan dihormati sebelum cookie tersebut digunakan. Menghapus data browser dapat mengatur ulang pilihan ini.</p>\n\n<h3>2. Penggunaan Informasi</h3>\n<p>Informasi yang Anda berikan digunakan untuk:</p>\n<ul>\n<li>Mengelola akun pengguna Anda</li>\n<li>Menyajikan konten yang relevan</li>\n<li>Meningkatkan layanan dan pengalaman pengguna</li>\n<li>Berkomunikasi dengan Anda mengenai pembaruan layanan</li>\n</ul>\n\n<h3>3. Keamanan Data</h3>\n<p>Kami mengimplementasikan langkah-langkah keamanan teknis dan organisasi untuk melindungi data Anda dari akses tidak sah, pengungkapan, atau perusakan.</p>\n\n<h3>4. Tidak Ada Penjualan Data</h3>\n<p>SEHATIN tidak menjual, menyewakan, atau membagikan data pribadi Anda kepada pihak ketiga untuk tujuan pemasaran.</p>\n\n<h3>5. Hubungi Kami</h3>\n<p>Jika Anda memiliki pertanyaan tentang Kebijakan Privasi ini, silakan hubungi tim kami melalui halaman kontak yang tersedia.</p>', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `static_pages` (`id`, `slug`, `title`, `content`, `created_at`, `updated_at`) VALUES (3, 'syarat-dan-ketentuan', 'Syarat dan Ketentuan', '<p><em>Terakhir diperbarui: 03 October 2026</em></p>\n\n<h2>Syarat dan Ketentuan Penggunaan SEHATIN</h2>\n<p>Dengan mengakses dan menggunakan platform SEHATIN, Anda menyetujui syarat dan ketentuan berikut. Harap baca dengan seksama sebelum menggunakan layanan kami.</p>\n\n<h3>1. Penerimaan Ketentuan</h3>\n<p>Penggunaan website SEHATIN berarti Anda setuju untuk terikat oleh Syarat dan Ketentuan ini, Kebijakan Privasi, serta semua peraturan yang berlaku.</p>\n\n<h3>2. Tujuan Informatif</h3>\n<p>Seluruh konten di SEHATIN disediakan untuk tujuan informasi dan edukasi semata. <strong>SEHATIN bukan pengganti layanan medis profesional.</strong></p>\n<div class="disclaimer-box">\n⚠️ Informasi di SEHATIN bersifat edukatif dan tidak menggantikan diagnosis atau konsultasi dengan tenaga kesehatan. Selalu konsultasikan kondisi kesehatan Anda dengan dokter atau tenaga medis yang berkualifikasi.\n</div>\n\n<h3>3. Akun Pengguna</h3>\n<ul>\n<li>Anda bertanggung jawab menjaga kerahasiaan akun Anda</li>\n<li>Anda tidak boleh berbagi akun dengan orang lain</li>\n<li>Segala aktivitas yang terjadi melalui akun Anda menjadi tanggung jawab Anda</li>\n</ul>\n\n<h3>4. Konten dan Hak Kekayaan Intelektual</h3>\n<p>Seluruh konten di SEHATIN, termasuk artikel, desain, dan logo, adalah milik SEHATIN dan dilindungi oleh hak cipta. Dilarang menyalin, mendistribusikan, atau menggunakan konten tanpa izin tertulis.</p>\n\n<h3>5. Batasan Tanggung Jawab</h3>\n<p>SEHATIN tidak bertanggung jawab atas kerugian yang timbul akibat penggunaan atau ketidakmampuan menggunakan layanan kami, termasuk kerugian yang timbul dari keputusan medis berdasarkan informasi di platform ini.</p>\n\n<h3>6. Perubahan Ketentuan</h3>\n<p>SEHATIN berhak mengubah syarat dan ketentuan ini sewaktu-waktu. Perubahan akan diberitahukan melalui website dan berlaku sejak tanggal publikasi.</p>', '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'Paracetamol', 'paracetamol', 'Parasetamol', 'bebas', 'tablet', 'Beragam produsen', 'Analgesik dan antipiretik untuk nyeri ringan hingga sedang dan demam.', 'Meredakan nyeri dan menurunkan demam; bukan mengobati penyebab penyakit.', 'Ikuti dosis pada kemasan atau petunjuk tenaga kesehatan; dosis anak harus berdasarkan berat badan.', 'Dapat diminum dengan atau tanpa makanan menggunakan air.', 'Jarang: mual atau ruam; overdosis dapat menyebabkan kerusakan hati berat.', 'Hipersensitivitas terhadap parasetamol.', 'Jangan melebihi dosis pada label dan jangan menggabungkan beberapa produk yang sama-sama mengandung parasetamol. Konsultasikan dahulu bila ada penyakit hati atau konsumsi alkohol rutin.', 'Rp2.000–Rp20.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Ibuprofen', 'ibuprofen', 'Ibuprofen', 'bebas', 'tablet', 'Beragam produsen', 'Obat antiinflamasi nonsteroid untuk nyeri, demam, dan peradangan.', 'Nyeri ringan hingga sedang, demam, dan peradangan tertentu sesuai label.', 'Gunakan dosis terendah selama waktu sesingkat mungkin sesuai label atau resep.', 'Minum dengan makanan atau susu untuk mengurangi iritasi lambung.', 'Nyeri ulu hati, mual, pusing; dapat meningkatkan risiko perdarahan lambung dan gangguan ginjal.', 'Alergi NSAID, riwayat perdarahan lambung aktif, atau gagal ginjal berat.', 'Hindari pada trimester akhir kehamilan. Konsultasikan bila memakai pengencer darah, memiliki penyakit ginjal/jantung, asma sensitif NSAID, atau dehidrasi.', 'Rp5.000–Rp30.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'Amoxicillin', 'amoxicillin', 'Amoksisilin', 'resep', 'kapsul', 'Beragam produsen', 'Antibiotik golongan penisilin untuk infeksi bakteri yang peka.', 'Infeksi bakteri tertentu berdasarkan diagnosis; tidak bermanfaat untuk flu atau infeksi virus.', 'Dosis dan lama terapi harus ditentukan dokter berdasarkan jenis infeksi, usia, berat badan, dan fungsi ginjal.', 'Gunakan tepat sesuai resep dan tuntaskan sesuai instruksi dokter; jangan berbagi antibiotik.', 'Mual, diare, ruam; reaksi alergi berat jarang tetapi dapat mengancam jiwa.', 'Alergi amoksisilin atau antibiotik penisilin.', 'Hanya dengan resep. Hentikan dan cari pertolongan bila muncul sesak, bengkak wajah, atau ruam berat. Beri tahu dokter bila ada gangguan ginjal atau riwayat alergi antibiotik.', 'Rp10.000–Rp80.000 per kemasan (tergantung dosis dan merek)', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'Antasida', 'antasida', 'Aluminium hidroksida dan magnesium hidroksida (komposisi dapat berbeda)', 'bebas', 'tablet', 'Beragam produsen', 'Sediaan penetral asam lambung; kandungan berbeda menurut produk.', 'Membantu meredakan gejala maag atau rasa panas di ulu hati untuk sementara.', 'Ikuti dosis serta batas pemakaian pada kemasan; bukan untuk penggunaan jangka panjang tanpa evaluasi.', 'Kunyah tablet hingga halus atau gunakan sediaan sesuai petunjuk. Beri jarak dengan obat lain sesuai label.', 'Konstipasi atau diare, bergantung kandungan.', 'Alergi terhadap komponen produk; sebagian produk perlu dihindari pada gangguan ginjal berat.', 'Periksa komposisi karena produk berbeda-beda. Konsultasikan jika gejala sering berulang, sulit menelan, muntah darah, atau tinja hitam.', 'Rp5.000–Rp35.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (5, 'Cetirizine', 'cetirizine', 'Cetirizine hidroklorida', 'bebas terbatas', 'tablet', 'Beragam produsen', 'Antihistamin untuk mengurangi gejala alergi.', 'Bersin, pilek alergi, mata berair/gatal, dan biduran.', 'Ikuti dosis pada label atau saran tenaga kesehatan; penyesuaian mungkin diperlukan pada gangguan ginjal.', 'Diminum dengan air; dapat diminum bersama atau tanpa makanan.', 'Mengantuk, lelah, mulut kering.', 'Hipersensitivitas terhadap cetirizine atau hydroxyzine.', 'Dapat menyebabkan kantuk; hindari mengemudi sampai mengetahui efeknya. Tanyakan kepada tenaga kesehatan bila hamil, menyusui, atau memiliki gangguan ginjal.', 'Rp5.000–Rp40.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (6, 'Omeprazole', 'omeprazole', 'Omeprazole', 'resep', 'kapsul', 'Beragam produsen', 'Penghambat pompa proton yang menurunkan produksi asam lambung.', 'GERD, tukak lambung, dan kondisi terkait asam lambung sesuai diagnosis.', 'Dosis dan lama terapi ditentukan dokter sesuai diagnosis.', 'Telan kapsul sesuai petunjuk produk; jangan menghancurkan sediaan lepas tunda kecuali label mengizinkan.', 'Sakit kepala, nyeri perut, mual, diare atau konstipasi.', 'Alergi omeprazole atau obat golongan sejenis.', 'Pemakaian lama perlu pemantauan. Informasikan obat lain, terutama clopidogrel dan obat dengan interaksi bermakna; segera periksa bila ada muntah darah atau tinja hitam.', 'Rp10.000–Rp100.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (7, 'Metformin', 'metformin', 'Metformin hidroklorida', 'resep', 'tablet', 'Beragam produsen', 'Obat antidiabetes golongan biguanid untuk membantu mengendalikan gula darah.', 'Diabetes tipe 2 bersama pola makan dan aktivitas fisik sesuai rencana dokter.', 'Dokter menentukan dosis dan penyesuaian berdasarkan gula darah serta fungsi ginjal.', 'Minum bersama makanan bila diarahkan; gunakan secara teratur sesuai resep.', 'Diare, mual, rasa tidak nyaman di perut; asidosis laktat sangat jarang tetapi serius.', 'Gangguan ginjal berat, asidosis metabolik, atau alergi metformin.', 'Perlu pemantauan fungsi ginjal. Beri tahu petugas medis sebelum pemeriksaan kontras atau operasi; jangan mengubah atau menghentikan obat tanpa arahan dokter.', 'Rp10.000–Rp100.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (8, 'Amlodipine', 'amlodipine', 'Amlodipin', 'resep', 'tablet', 'Beragam produsen', 'Obat penghambat kanal kalsium untuk tekanan darah dan kondisi jantung tertentu.', 'Hipertensi dan angina sesuai evaluasi dokter.', 'Dosis individual ditentukan dokter dan dipantau berkala.', 'Minum pada waktu yang sama setiap hari sesuai resep.', 'Bengkak pada pergelangan kaki, pusing, kemerahan, atau lelah.', 'Alergi amlodipin.', 'Jangan menghentikan obat tanpa konsultasi. Bangun perlahan bila pusing; laporkan bengkak berat atau nyeri dada yang memburuk.', 'Rp10.000–Rp100.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (9, 'Simvastatin', 'simvastatin', 'Simvastatin', 'resep', 'tablet', 'Beragam produsen', 'Obat golongan statin untuk membantu menurunkan kolesterol.', 'Menurunkan risiko kardiovaskular dan kolesterol sesuai penilaian dokter.', 'Dokter menentukan dosis berdasarkan risiko dan respons; pemeriksaan berkala mungkin diperlukan.', 'Minum sesuai resep pada waktu yang diarahkan; hindari grapefruit bila dokter/label memperingatkan.', 'Nyeri otot atau gangguan pencernaan; kerusakan otot/hati jarang namun serius.', 'Kehamilan, penyakit hati aktif, atau penggunaan obat tertentu yang berinteraksi.', 'Segera hubungi tenaga kesehatan jika nyeri atau kelemahan otot berat, urin gelap, atau kulit/mata menguning. Informasikan semua obat yang digunakan.', 'Rp10.000–Rp100.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (10, 'Vitamin C', 'vitamin-c', 'Asam askorbat', 'bebas', 'tablet', 'Beragam produsen', 'Vitamin larut air yang berperan dalam pembentukan kolagen dan fungsi normal tubuh.', 'Mencegah atau mengatasi kekurangan vitamin C; tidak terbukti menyembuhkan flu.', 'Penuhi kebutuhan sesuai usia dan label; hindari dosis tinggi tanpa saran tenaga kesehatan.', 'Diminum dengan air; ikuti petunjuk produk.', 'Dosis tinggi dapat menyebabkan mual, diare, atau meningkatkan risiko batu ginjal pada sebagian orang.', 'Hipersensitivitas terhadap komponen produk.', 'Konsultasikan bila memiliki riwayat batu ginjal, gangguan penyerapan zat besi, sedang hamil/menyusui, atau mengonsumsi obat rutin.', 'Rp5.000–Rp60.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (11, 'Vitamin D3', 'vitamin-d3', 'Kolekalsiferol', 'bebas terbatas', 'kapsul', 'Beragam produsen', 'Vitamin larut lemak yang membantu penyerapan kalsium dan kesehatan tulang.', 'Pencegahan atau penanganan kekurangan vitamin D sesuai evaluasi klinis.', 'Kebutuhan bergantung usia, pola paparan matahari, kadar vitamin, dan kondisi klinis; ikuti saran dokter/label.', 'Minum sesuai petunjuk produk; penyerapan dapat lebih baik bersama makanan.', 'Dosis berlebihan dapat menyebabkan kadar kalsium tinggi, mual, lemah, dan gangguan ginjal.', 'Hiperkalsemia atau hipervitaminosis D; konsultasikan bila memiliki penyakit tertentu.', 'Jangan menggunakan dosis tinggi berkepanjangan tanpa pemeriksaan. Beri tahu dokter bila memakai diuretik thiazide atau digoxin.', 'Rp10.000–Rp120.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (12, 'Zinc', 'zinc', 'Seng (zinc)', 'bebas terbatas', 'tablet', 'Beragam produsen', 'Mineral esensial yang dibutuhkan tubuh dalam jumlah kecil.', 'Membantu memenuhi kebutuhan seng; terapi diare anak hanya mengikuti pedoman dan arahan tenaga kesehatan.', 'Ikuti dosis sesuai kelompok usia dan petunjuk tenaga kesehatan; kebutuhan anak dan dewasa berbeda.', 'Minum sesuai label. Jarakkan dari antibiotik tertentu dan zat besi sesuai anjuran apoteker.', 'Mual, rasa logam, dan nyeri perut; pemakaian dosis tinggi lama dapat menyebabkan kekurangan tembaga.', 'Hipersensitivitas terhadap komponen produk.', 'Suplemen bukan pengganti makanan bergizi. Konsultasikan bila hamil/menyusui atau menggunakan obat rutin.', 'Rp5.000–Rp60.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (13, 'ORS / Oralit', 'ors-oralit', 'Garam rehidrasi oral (glukosa dan elektrolit)', 'bebas', 'serbuk', 'Beragam produsen', 'Larutan rehidrasi oral untuk mengganti cairan dan elektrolit yang hilang.', 'Mencegah dan menangani dehidrasi ringan akibat diare atau muntah.', 'Larutkan satu sachet dalam volume air bersih yang persis tertera pada kemasan; jangan mengubah takaran.', 'Gunakan air matang yang telah dingin atau air bersih sesuai petunjuk; berikan sedikit-sedikit dan buang sisa sesuai label.', 'Mual atau muntah bila diminum terlalu cepat.', 'Tidak ada kontraindikasi umum; dehidrasi berat memerlukan pertolongan medis, bukan hanya oralit.', 'Cari bantuan bila tidak mampu minum, sangat lemas, urine sangat sedikit, ada darah pada tinja, atau tanda dehidrasi berat. Jangan menambahkan gula/garam.', 'Rp1.000–Rp10.000 per sachet', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (14, 'Loperamide', 'loperamide', 'Loperamide hidroklorida', 'bebas terbatas', 'tablet', 'Beragam produsen', 'Obat antidiare yang memperlambat gerakan usus untuk kondisi tertentu.', 'Meredakan diare akut tanpa komplikasi pada orang dewasa sesuai label.', 'Gunakan hanya sesuai label dan batas durasi/dosis pada kemasan; jangan digunakan pada anak tanpa arahan tenaga kesehatan.', 'Minum dengan air; tetap ganti cairan menggunakan oralit.', 'Konstipasi, kram perut, mual; overdosis dapat menyebabkan gangguan irama jantung yang fatal.', 'Diare berdarah atau disertai demam tinggi, kolitis berat, atau alergi loperamide.', 'Hentikan dan periksa bila tidak membaik sesuai batas waktu label, perut membuncit, atau muncul darah/demam. Bukan pengganti rehidrasi.', 'Rp5.000–Rp40.000 per kemasan', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `drugs` (`id`, `name`, `slug`, `generic_name`, `category`, `form`, `manufacturer`, `content`, `indication`, `dosage`, `how_to_use`, `side_effects`, `contraindication`, `warning`, `price_range`, `is_active`, `created_at`, `updated_at`) VALUES (15, 'Salbutamol', 'salbutamol', 'Salbutamol (albuterol)', 'resep', 'inhaler', 'Beragam produsen', 'Bronkodilator kerja cepat yang melemaskan otot saluran napas.', 'Meredakan bronkospasme pada asma atau kondisi lain sesuai rencana dokter.', 'Gunakan sesuai resep dan rencana aksi asma; kebutuhan yang makin sering perlu evaluasi dokter.', 'Gunakan teknik inhalasi yang benar; minta demonstrasi tenaga kesehatan dan bersihkan alat sesuai petunjuk.', 'Tremor, berdebar, sakit kepala, atau gelisah.', 'Alergi terhadap salbutamol atau komponen sediaan.', 'Bukan pengganti obat pengontrol asma. Cari pertolongan darurat bila sesak berat atau inhaler pereda tidak membantu sesuai rencana.', 'Rp50.000–Rp250.000 per inhaler', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'Demam Berdarah', 'demam-berdarah', 'kesehatan-umum', 'Demam berdarah dengue (DBD) adalah infeksi virus dengue yang ditularkan terutama melalui gigitan nyamuk Aedes. Derajatnya bervariasi dan dapat menjadi berat.', 'Demam tinggi, nyeri kepala/belakang mata, nyeri otot, mual, ruam; tanda bahaya meliputi nyeri perut hebat, muntah terus-menerus, perdarahan, gelisah atau sangat lemas.', 'Virus dengue yang ditularkan nyamuk Aedes yang terinfeksi.', 'Tinggal atau bepergian ke daerah dengan penularan dengue; infeksi dengue sebelumnya dapat meningkatkan risiko dengue berat.', 'Penilaian klinis dan pemeriksaan darah sesuai hari sakit; hasil laboratorium perlu ditafsirkan tenaga kesehatan.', 'Tidak ada antivirus khusus. Cairan, pemantauan, dan perawatan suportif diberikan sesuai kondisi. Hindari aspirin/ibuprofen tanpa arahan dokter karena risiko perdarahan.', 'Cegah gigitan nyamuk, hilangkan genangan, tutup tempat air, gunakan repelan dan kelambu/pakaian pelindung.', 'Segera ke fasilitas kesehatan bila ada tanda bahaya, perdarahan, sulit minum, urine berkurang, sesak, atau kesadaran berubah.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Hipertensi', 'hipertensi', 'kesehatan-umum', 'Hipertensi adalah tekanan darah yang menetap di atas batas diagnosis yang ditentukan pedoman klinis. Sering tidak bergejala, tetapi meningkatkan risiko penyakit jantung, stroke, dan ginjal.', 'Sering tanpa gejala. Tekanan sangat tinggi dapat disertai nyeri dada, sesak, gangguan penglihatan, sakit kepala berat, atau kelemahan mendadak.', 'Dipengaruhi gabungan faktor genetik, usia, kondisi kesehatan, dan gaya hidup.', 'Usia bertambah, riwayat keluarga, konsumsi garam tinggi, kurang aktivitas, berat badan berlebih, merokok, alkohol, penyakit ginjal, dan diabetes.', 'Pengukuran berulang dengan teknik yang benar; kadang pemantauan di rumah/24 jam serta pemeriksaan risiko organ.', 'Perubahan gaya hidup dan obat bila diperlukan berdasarkan penilaian dokter. Jangan menghentikan obat ketika tekanan sudah membaik tanpa arahan.', 'Batasi garam, aktif bergerak, jaga berat badan, tidak merokok, batasi alkohol, dan lakukan pemeriksaan rutin.', 'Konsultasi untuk hasil berulang tinggi. Keadaan darurat seperti nyeri dada, sesak, kebingungan, atau gejala stroke perlu pertolongan segera.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'Diabetes Tipe 2', 'diabetes-tipe-2', 'diet-dan-nutrisi', 'Diabetes tipe 2 terjadi ketika tubuh tidak menggunakan insulin secara efektif dan/atau produksi insulin tidak mencukupi sehingga gula darah meningkat.', 'Sering tanpa gejala; dapat berupa sering haus/berkemih, mudah lelah, pandangan kabur, luka lambat sembuh, atau infeksi berulang.', 'Resistensi insulin dan penurunan fungsi sel beta pankreas, dipengaruhi faktor genetik dan lingkungan.', 'Riwayat keluarga, usia, berat badan berlebih, kurang aktivitas fisik, diabetes gestasional sebelumnya, dan beberapa kondisi metabolik.', 'Pemeriksaan gula darah puasa, HbA1c, atau tes lain sesuai kriteria dan konfirmasi tenaga kesehatan.', 'Rencana individual berupa pola makan, aktivitas fisik, pemantauan, dan obat/insulin bila dibutuhkan.', 'Pemeriksaan berkala, pola makan seimbang, aktivitas fisik rutin, tidur cukup, dan hindari merokok.', 'Periksa bila gejala muncul atau hasil skrining tinggi. Cari bantuan segera untuk muntah, dehidrasi, napas cepat, kebingungan, atau penurunan kesadaran.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'Asma', 'asma', 'kesehatan-umum', 'Asma adalah penyakit kronis saluran napas dengan peradangan dan penyempitan yang berubah-ubah, menyebabkan gejala berulang.', 'Mengi, sesak, dada terasa berat, dan batuk; sering memburuk malam/dini hari atau setelah pemicu.', 'Peradangan saluran napas dengan faktor kerentanan genetik dan pemicu lingkungan.', 'Alergi, riwayat keluarga, asap rokok, polusi, alergen, infeksi virus, atau paparan kerja tertentu.', 'Riwayat gejala dan pemeriksaan fungsi paru seperti spirometri bila memungkinkan; evaluasi klinis menentukan diagnosis.', 'Obat pengontrol dan pereda sesuai rencana tertulis dari dokter; teknik inhaler perlu diperiksa berkala.', 'Kenali dan kurangi pemicu, hindari asap rokok, gunakan obat sesuai rencana dan kontrol rutin.', 'Ke IGD bila sesak berat, sulit bicara, bibir kebiruan, atau obat pereda tidak membantu sesuai rencana aksi asma.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (5, 'Maag / GERD', 'maag-gerd', 'kesehatan-umum', 'GERD terjadi ketika isi lambung berulang kali naik ke kerongkongan dan menimbulkan gejala atau komplikasi. Istilah maag sering dipakai untuk berbagai keluhan perut atas.', 'Rasa terbakar di dada/ulu hati, regurgitasi asam, rasa asam di mulut; kadang batuk atau suara serak.', 'Refluks isi lambung; dapat dipengaruhi fungsi sfingter, pola makan, dan kondisi tertentu.', 'Makan besar larut malam, berat badan berlebih, kehamilan, merokok, dan pemicu individual.', 'Berdasarkan gejala dan pemeriksaan; endoskopi atau tes lain bila ada tanda bahaya atau indikasi klinis.', 'Perubahan kebiasaan dan terapi obat sesuai evaluasi tenaga kesehatan; jangan menggunakan obat jangka panjang tanpa penilaian.', 'Makan porsi wajar, tidak berbaring segera setelah makan, identifikasi pemicu, berhenti merokok, dan kelola berat badan.', 'Periksa bila sering kambuh, sulit/nyeri menelan, muntah darah, tinja hitam, berat badan turun tanpa sebab, atau nyeri dada.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (6, 'Flu & Batuk', 'flu-batuk', 'kesehatan-umum', 'Flu adalah infeksi saluran pernapasan akibat virus influenza; batuk juga dapat disebabkan banyak virus atau kondisi lain. Pilek biasa tidak selalu influenza.', 'Demam, batuk, nyeri tenggorokan, pilek, nyeri otot, sakit kepala, dan lelah; derajat gejala bervariasi.', 'Penularan virus melalui droplet/aerosol dan tangan/permukaan yang terkontaminasi.', 'Kontak erat, musim penularan, belum mendapat vaksin influenza, usia lanjut, kehamilan, atau penyakit kronis.', 'Biasanya klinis; tes influenza/COVID-19 dapat dipertimbangkan sesuai situasi dan kebijakan setempat.', 'Istirahat, cairan, dan perawatan gejala. Antivirus influenza tertentu hanya dengan evaluasi dan resep, terutama untuk kelompok berisiko.', 'Vaksinasi sesuai anjuran, cuci tangan, etika batuk, ventilasi baik, dan tinggal di rumah saat sakit.', 'Cari pertolongan untuk sesak, nyeri dada, kebingungan, dehidrasi, bibir kebiruan, atau gejala memburuk/berkepanjangan.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (7, 'Diare', 'diare', 'kesehatan-umum', 'Diare adalah buang air besar cair atau lembek lebih sering dari biasanya. Risiko utamanya adalah dehidrasi.', 'Tinja cair berulang, kram perut, mual; dehidrasi dapat menyebabkan haus, mulut kering, lemas, dan urine berkurang.', 'Infeksi virus, bakteri, atau parasit; juga dapat dipicu obat, intoleransi, atau kondisi usus.', 'Air/makanan tercemar, sanitasi buruk, kontak dengan orang sakit, usia sangat muda atau lanjut.', 'Riwayat dan pemeriksaan; tes tinja/darah dipertimbangkan untuk gejala berat, lama, berdarah, atau kondisi tertentu.', 'Rehidrasi oral merupakan hal penting; terapi lain sesuai penyebab dan penilaian tenaga kesehatan.', 'Cuci tangan, air minum aman, makanan matang, sanitasi baik, dan vaksin rotavirus untuk anak sesuai jadwal.', 'Segera periksa bila ada darah, demam tinggi, nyeri hebat, tidak mampu minum, tanda dehidrasi, atau terjadi pada bayi/lansia dengan kondisi memburuk.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (8, 'Anemia', 'anemia', 'kesehatan-umum', 'Anemia adalah kondisi ketika kadar hemoglobin atau jumlah sel darah merah tidak mencukupi untuk membawa oksigen secara optimal.', 'Lelah, pucat, lemah, pusing, sesak saat aktivitas, jantung berdebar; gejala bergantung penyebab dan tingkat keparahan.', 'Kekurangan zat besi/nutrisi lain, perdarahan, penyakit kronis, gangguan genetik, atau masalah produksi/penghancuran sel darah.', 'Menstruasi berat, kehamilan, asupan kurang, perdarahan saluran cerna, penyakit kronis, atau riwayat keluarga.', 'Pemeriksaan darah lengkap dan tes lanjutan sesuai dugaan penyebab; tidak semua anemia disebabkan kekurangan zat besi.', 'Penanganan menargetkan penyebab; suplemen hanya bila dianjurkan setelah evaluasi.', 'Pola makan beragam dan pemeriksaan/penanganan penyebab perdarahan atau penyakit kronis.', 'Konsultasi bila lelah/pucat menetap. Pertolongan segera untuk sesak saat istirahat, nyeri dada, pingsan, perdarahan banyak, atau kelemahan berat.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (9, 'TBC', 'tbc', 'kesehatan-umum', 'Tuberkulosis adalah penyakit infeksi oleh bakteri Mycobacterium tuberculosis, paling sering menyerang paru dan dapat menular melalui udara.', 'Batuk menetap, dahak atau darah, demam, keringat malam, berat badan turun, lelah; gejala di luar paru bervariasi.', 'Menghirup partikel udara dari penderita TBC aktif yang menular; bukan melalui berbagi alat makan biasa.', 'Kontak erat, HIV/imunosupresi, malnutrisi, diabetes, merokok, atau tinggal di lingkungan padat.', 'Pemeriksaan dahak/tes molekuler, pencitraan, dan evaluasi klinis sesuai program/pedoman setempat.', 'Kombinasi obat antituberkulosis dalam regimen lengkap yang ditentukan program/dokter; kepatuhan sangat penting.', 'Ventilasi baik, etika batuk, skrining kontak, pengobatan dini, serta vaksin BCG sesuai jadwal nasional.', 'Segera periksa bila batuk lama, batuk darah, berat badan turun, atau kontak erat dengan pasien TBC.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `diseases` (`id`, `name`, `slug`, `category`, `overview`, `symptoms`, `causes`, `risk_factors`, `diagnosis`, `treatment`, `prevention`, `when_to_see_doctor`, `is_active`, `created_at`, `updated_at`) VALUES (10, 'Kolesterol Tinggi', 'kolesterol-tinggi', 'kesehatan-umum', 'Dislipidemia adalah kadar lipid darah yang tidak sehat, termasuk LDL tinggi atau HDL rendah, dan dapat meningkatkan risiko aterosklerosis.', 'Biasanya tidak menimbulkan gejala; diketahui melalui pemeriksaan darah.', 'Dipengaruhi genetik, pola makan, metabolisme, kondisi medis, serta beberapa obat.', 'Riwayat keluarga, diabetes, hipertensi, merokok, kurang aktivitas, pola makan tinggi lemak jenuh/trans, dan usia.', 'Profil lipid darah ditafsirkan bersama faktor risiko kardiovaskular oleh tenaga kesehatan.', 'Perubahan gaya hidup dan obat penurun lipid bila manfaatnya dinilai sesuai risiko.', 'Pola makan kaya sayur/buah/serat, aktivitas fisik, berhenti merokok, dan kontrol faktor risiko lain.', 'Lakukan skrining sesuai anjuran. Nyeri dada mendadak, sesak, atau gejala stroke memerlukan pertolongan darurat.', 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (1, 'Panduan Gizi Seimbang', 'panduan-gizi-seimbang', 'nutrisi', 'Prinsip sederhana menyusun makanan beragam, bergizi, seimbang, dan aman.', '<p>Gizi seimbang membantu memenuhi kebutuhan tubuh melalui makanan beragam, aktivitas fisik, perilaku hidup bersih, dan pemantauan berat badan.</p><h2>Isi piring dengan beragam pangan</h2><p>Utamakan sayur dan buah, sumber karbohidrat, serta lauk berprotein. Proporsi dapat disesuaikan dengan kebutuhan, usia, budaya, dan kondisi kesehatan.</p><ul><li>Pilih sumber karbohidrat beragam seperti nasi, jagung, kentang, atau umbi.</li><li>Sertakan lauk berprotein hewani atau nabati.</li><li>Perbanyak sayur dan buah dengan warna beragam.</li><li>Batasi gula, garam, dan lemak berlebih serta pilih air minum yang aman.</li></ul><h2>Kebiasaan pendukung</h2><p>Biasakan cuci tangan, aktif bergerak, dan timbang berat badan secara berkala. Kebutuhan khusus sebaiknya dibahas dengan ahli gizi atau tenaga kesehatan.</p>', 'fas fa-apple-alt', 1, 1, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (2, 'Olahraga untuk Pemula', 'olahraga-untuk-pemula', 'olahraga', 'Mulai bergerak secara bertahap, aman, dan konsisten sesuai kemampuan.', '<p>Aktivitas fisik teratur bermanfaat bagi kebugaran dan kesehatan jangka panjang. Mulailah dari tingkat yang nyaman; sedikit aktivitas lebih baik daripada tidak bergerak.</p><h2>Mulai dengan aman</h2><ul><li>Pilih kegiatan yang disukai, seperti jalan kaki, bersepeda santai, atau senam ringan.</li><li>Awali dengan durasi dan intensitas ringan, lalu tingkatkan bertahap.</li><li>Lakukan pemanasan dan pendinginan serta gunakan alas kaki yang sesuai.</li><li>Sisipkan latihan kekuatan dan keseimbangan sesuai kemampuan.</li></ul><h2>Dengarkan tubuh</h2><p>Beristirahat dan minum sesuai kebutuhan. Hentikan aktivitas dan cari pertolongan bila timbul nyeri dada, pingsan, atau sesak yang tidak wajar. Konsultasikan rencana olahraga jika memiliki penyakit kronis, sedang hamil, atau lama tidak aktif.</p>', 'fas fa-person-running', 1, 2, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (3, 'Tidur Berkualitas', 'tidur-berkualitas', 'tidur', 'Bangun rutinitas tidur yang mendukung istirahat dan pemulihan tubuh.', '<p>Tidur yang cukup dan berkualitas mendukung konsentrasi, suasana hati, dan kesehatan. Kebutuhan tidur berbeda menurut usia dan kondisi individu.</p><h2>Kebiasaan yang membantu</h2><ul><li>Usahakan waktu tidur dan bangun yang teratur, termasuk akhir pekan.</li><li>Jadikan kamar nyaman, gelap, tenang, dan tidak terlalu panas.</li><li>Kurangi kafein menjelang waktu tidur dan hindari makan berat larut malam.</li><li>Batasi layar sebelum tidur dan lakukan kegiatan menenangkan.</li><li>Beraktivitas fisik pada siang hari, bukan tepat sebelum tidur bila mengganggu.</li></ul><p>Bicarakan dengan tenaga kesehatan bila sulit tidur berlangsung lama, mendengkur disertai henti napas, atau rasa kantuk mengganggu aktivitas siang hari.</p>', 'fas fa-moon', 1, 3, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (4, 'Manajemen Stres', 'manajemen-stres', 'mental', 'Kenali pemicu stres dan gunakan strategi sehat untuk menghadapinya.', '<p>Stres adalah respons terhadap tuntutan atau perubahan. Respons setiap orang berbeda; mencari dukungan merupakan bagian dari menjaga kesehatan.</p><h2>Langkah sederhana</h2><ul><li>Kenali situasi dan tanda tubuh saat stres mulai meningkat.</li><li>Atur tugas menjadi langkah kecil dan sisihkan waktu untuk istirahat.</li><li>Coba latihan napas perlahan, peregangan, atau kegiatan yang menenangkan.</li><li>Jaga tidur, makan teratur, aktivitas fisik, serta hubungan sosial yang suportif.</li><li>Bicaralah dengan orang tepercaya dan tetapkan batas yang sehat.</li></ul><p>Jika stres berkepanjangan mengganggu fungsi sehari-hari, konsultasikan dengan tenaga kesehatan mental. Bila ada risiko menyakiti diri sendiri atau orang lain, cari bantuan darurat setempat segera.</p>', 'fas fa-brain', 1, 4, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (5, 'Cuci Tangan yang Benar', 'cuci-tangan-yang-benar', 'kebersihan', 'Langkah cuci tangan dengan sabun untuk membantu mengurangi penyebaran kuman.', '<p>Cuci tangan dengan sabun dan air mengalir membantu mengurangi penyebaran kuman penyebab penyakit.</p><h2>Langkah cuci tangan</h2><ol><li>Basahi tangan dengan air bersih dan gunakan sabun.</li><li>Gosok telapak tangan, punggung tangan, sela jari, ibu jari, ujung jari, kuku, dan pergelangan.</li><li>Gosok seluruh permukaan setidaknya 20 detik.</li><li>Bilas di bawah air mengalir dan keringkan dengan kain/tisu bersih.</li></ol><h2>Kapan perlu mencuci tangan?</h2><p>Sebelum menyiapkan atau makan makanan, setelah dari toilet, setelah batuk/bersin, setelah merawat orang sakit, dan ketika tangan tampak kotor. Jika air dan sabun tidak tersedia, gunakan pembersih tangan berbasis alkohol sesuai petunjuk.</p>', 'fas fa-hands-bubbles', 1, 5, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (6, 'Pola Makan Diabetes', 'pola-makan-diabetes', 'nutrisi', 'Panduan umum pola makan teratur dan beragam untuk membantu pengelolaan diabetes.', '<p>Pola makan diabetes perlu disesuaikan dengan obat, aktivitas, budaya, kondisi kesehatan, dan preferensi. Tidak ada satu pola yang cocok bagi semua orang.</p><h2>Prinsip umum</h2><ul><li>Atur waktu makan secara konsisten sesuai rencana perawatan.</li><li>Pilih sayur, buah utuh, kacang-kacangan, biji-bijian utuh, dan sumber protein beragam.</li><li>Perhatikan porsi sumber karbohidrat dan minuman manis; air putih menjadi pilihan utama.</li><li>Batasi makanan tinggi gula tambahan, garam, dan lemak jenuh.</li></ul><p>Jangan melewatkan makan atau mengubah obat untuk menyesuaikan makanan tanpa arahan klinisi. Ahli gizi dan dokter dapat membantu menyusun rencana yang aman dan realistis.</p>', 'fas fa-bowl-food', 1, 6, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (7, 'Menjaga Kesehatan Jantung', 'menjaga-kesehatan-jantung', 'olahraga', 'Kebiasaan harian dan pemeriksaan rutin membantu menjaga kesehatan jantung.', '<p>Kesehatan jantung dipengaruhi tekanan darah, kolesterol, gula darah, kebiasaan merokok, aktivitas, pola makan, dan faktor lainnya.</p><h2>Jaga kesehatan jantung</h2><ul><li>Bergerak secara teratur dan kurangi waktu duduk berkepanjangan.</li><li>Pilih makanan beragam dengan sayur, buah, kacang-kacangan, dan serat.</li><li>Batasi garam, lemak trans, dan lemak jenuh berlebih.</li><li>Hindari rokok dan asap rokok; batasi atau hindari alkohol.</li><li>Periksa tekanan darah, gula, dan kolesterol sesuai anjuran.</li><li>Gunakan obat yang diresepkan secara teratur dan diskusikan efek sampingnya.</li></ul><p>Nyeri/tekanan dada, sesak mendadak, atau gejala stroke adalah keadaan darurat—segera cari bantuan.</p>', 'fas fa-heart-pulse', 1, 7, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (8, 'Kesehatan Mental Remaja', 'kesehatan-mental-remaja', 'mental', 'Dukungan, komunikasi terbuka, dan kebiasaan sehat penting bagi kesejahteraan remaja.', '<p>Masa remaja membawa perubahan fisik, sosial, dan emosional. Perasaan sedih atau cemas sesekali dapat terjadi, namun gejala yang menetap dan mengganggu layak mendapat perhatian.</p><h2>Dukungan yang bermanfaat</h2><ul><li>Bangun komunikasi yang mendengarkan tanpa menghakimi.</li><li>Jaga rutinitas tidur, aktivitas fisik, makan, dan waktu istirahat.</li><li>Perkuat hubungan aman dengan keluarga, teman, guru, atau orang dewasa tepercaya.</li><li>Gunakan media sosial dengan batas yang sehat dan laporkan perundungan.</li><li>Libatkan konselor atau tenaga kesehatan bila dibutuhkan.</li></ul><p>Jika remaja menunjukkan risiko menyakiti diri, kekerasan, atau bahaya langsung, jangan tinggalkan sendirian dan hubungi layanan darurat/tenaga profesional setempat.</p>', 'fas fa-people-group', 1, 8, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (9, 'Imunisasi Anak', 'imunisasi-anak', 'lainnya', 'Imunisasi melindungi anak dari penyakit yang dapat dicegah dengan vaksin.', '<p>Vaksin membantu sistem kekebalan mengenali penyakit tertentu dan mengurangi risiko sakit berat. Jadwal imunisasi mengikuti program nasional serta kondisi anak.</p><h2>Hal yang perlu dilakukan orang tua</h2><ul><li>Ikuti jadwal imunisasi rutin dari fasilitas kesehatan dan simpan buku/catatan imunisasi.</li><li>Tanyakan kepada petugas bila jadwal terlewat; banyak dosis dapat dijadwalkan kejar.</li><li>Sampaikan riwayat alergi berat atau reaksi sebelumnya kepada petugas.</li><li>Efek ringan seperti nyeri di lokasi suntikan atau demam singkat dapat terjadi; minta panduan penanganannya.</li></ul><p>Jangan menunda vaksin hanya karena pilek ringan tanpa bertanya kepada tenaga kesehatan. Keputusan pada kondisi khusus dibuat bersama petugas imunisasi.</p>', 'fas fa-syringe', 1, 9, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
INSERT INTO `health_guides` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `icon`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (10, 'Pertolongan Pertama Demam', 'pertolongan-pertama-demam', 'lainnya', 'Cara memantau demam dengan aman dan mengenali kapan perlu bantuan medis.', '<p>Demam merupakan gejala, bukan penyakit tersendiri. Perhatikan kondisi umum, usia, lama demam, serta tanda bahaya.</p><h2>Perawatan awal</h2><ul><li>Ukur suhu dengan termometer dan catat hasil serta waktunya.</li><li>Berikan cairan lebih sering dan biarkan beristirahat dengan pakaian nyaman.</li><li>Gunakan obat penurun demam hanya sesuai label dan dosis berdasarkan usia/berat badan atau arahan tenaga kesehatan.</li><li>Hindari kompres es, alkohol, atau pemberian aspirin pada anak.</li></ul><h2>Kapan perlu segera diperiksa?</h2><p>Bayi di bawah 3 bulan dengan suhu 38°C atau lebih perlu penilaian medis segera. Cari bantuan untuk sesak, kejang, sulit dibangunkan, leher kaku, ruam yang mengkhawatirkan, dehidrasi, atau kondisi memburuk. Demam dengue memerlukan perhatian khusus dan hindari ibuprofen/aspirin bila dicurigai tanpa arahan dokter.</p>', 'fas fa-temperature-high', 1, 10, '2026-10-03 13:53:15', '2026-10-03 13:53:15');
